"""Complete original E08 collision vertices for evaluator-only containment.

The cached vertices come from every enabled original collision mesh after the
same source rotation/visual centering/normalization as the loaded rigid actor.
The two unchanged USD SHA256 values bind the cache. Physics/scene specs, cavity
bounds, contact forces and native tolerances are never modified here.
"""
import base64
import gzip
import hashlib
import json
from functools import lru_cache
import numpy as np

_DATA_SHA256 = 'f2252e620721fbbd3160e6c36ab207cb445a417df0253b50bbed1dc4be9bbe5f'
_DATA_GZIP_BASE64 = ''

@lru_cache(maxsize=1)
def _geometry():
    raw=gzip.decompress(base64.b64decode(_DATA_GZIP_BASE64))
    if hashlib.sha256(raw).hexdigest()!=_DATA_SHA256:raise ValueError('Original E08 source vertex cache SHA mismatch')
    return json.loads(raw)


def bind_original_e08_evaluator_geometry(private_spec):
    """Augment only an evaluator-owned spec; source scene identity stays exact."""
    if private_spec['id']!='E08':return
    sources=_geometry();matched=[]
    for obj in private_spec['objects']:
        source=obj.get('source_asset',{});sha=source.get('sha256')
        if sha not in sources:continue
        entry=sources[sha]
        if not np.allclose(source.get('source_rotation',[]),entry['source_rotation'],atol=1e-12,rtol=0):
            raise ValueError('Original E08 source rotation differs from reviewed collision vertex cache')
        half=np.asarray(obj['size'],float)
        if half.shape!=(3,)or not np.isfinite(half).all()or np.any(half<=0):raise ValueError('Original E08 loaded body dimensions required')
        points=np.asarray(entry['points'],float)*half/np.asarray(entry['half_size'],float)
        if len(points)!=3729 or entry['source_collision_mesh_count']!=22:raise ValueError('Complete original E08 collision source required')
        obj['containment_points_local']=points.tolist();obj['containment_points_source_sha256']=sha;matched.append(obj['id'])
    shoes=private_spec['semantic'].get('groups',{}).get('shoes',[])
    if matched:
        if set(matched)!=set(shoes):raise ValueError('Original E08 source geometry must cover both source shoes')
        private_spec['semantic']['source_acceptance_geometry']='E08-source-geometry-v1'
